create table if not exists users(id bigserial primary key,email text unique not null,password_hash text not null,display_name text not null,timezone text not null default 'UTC',created_at timestamptz not null default now());
create table if not exists follow_ups(id bigserial primary key,user_id bigint not null references users(id) on delete cascade,client_label text not null,task text not null,notes text,priority text not null default 'normal' check(priority in('low','normal','high','urgent')),status text not null default 'upcoming' check(status in('upcoming','completed')),due_at timestamptz not null,completed_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists activity_history(id bigserial primary key,follow_up_id bigint not null references follow_ups(id) on delete cascade,user_id bigint not null references users(id) on delete cascade,event_type text not null,detail text,created_at timestamptz not null default now());
create index if not exists follow_ups_user_due_idx on follow_ups(user_id,due_at);
create index if not exists activity_follow_up_idx on activity_history(follow_up_id,created_at desc);
